    }
],
"locations": [
    "Darklake tunnel",
    "Islet of limestone and stalagmites",
    "Large stalactite with lair of Zombie Beholder",
    "Bottom of the Darklake"
],
"threats": [
    "Zombie Beholder",
    "Duergar zombies",
    "Derro zombies",
    "Zombie Beholder (alternate)",
